T = TypeVar("T")


def get_weighted_random_species(random: Random, fbd: dict[int, list[T]]) -> T:
    forms = fbd[random.choice(tuple(fbd))]
    if len(forms) == 1:
        return forms[0]
    else:
        return random.choice(forms)
